"use client";

import {
  createContext,
  use,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import type {
  ComponentProps,
  CSSProperties,
  PointerEvent as ReactPointerEvent,
  ReactNode,
  RefObject,
} from "react";

import { cn } from "@/lib/utils";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";
import { foldCorner, restingTip } from "@/registry/ivan/lib/page-fold";

import {
  createPeelController,
  flapShadeSpan,
  peelLegs,
  undersideShadeSpan,
} from "./peel-controller";
import type { PeelController, PeelHandle } from "./peel-controller";

type PeelScope = "viewport" | "container";

interface PagePeelContextValue {
  isOpen: boolean;
  toggle: () => void;
  undersideId: string;
}

const PagePeelContext = createContext<PagePeelContextValue | null>(null);

const positionClassNames: Record<PeelScope, string> = {
  container: "absolute",
  viewport: "fixed",
};

const restLeg = `${peelLegs.corner.rest}px`;
const foldLeg = `${peelLegs.fold.rest}px`;
const referenceStage = { height: 1000, width: 1000 };
const restFold = foldCorner(
  referenceStage,
  restingTip(referenceStage, peelLegs.corner.rest)
);
const restAnchor = `translate(${restFold.midpoint.x - referenceStage.width}px, ${restFold.midpoint.y - referenceStage.height}px)`;

const undersideStyle: CSSProperties = {
  clipPath: `polygon(100% calc(100% - ${restLeg}), 100% 100%, calc(100% - ${restLeg}) 100%)`,
};

const flapStyle: CSSProperties = {
  backgroundColor:
    "color-mix(in oklch, var(--background) 92%, var(--foreground))",
  clipPath: `polygon(100% calc(100% - ${restLeg}), calc(100% - ${restLeg}) calc(100% - ${restLeg}), calc(100% - ${restLeg}) 100%)`,
};

const flapShadeStyle: CSSProperties = {
  backgroundImage:
    "linear-gradient(to right, color-mix(in oklch, var(--background) 74%, black) 0%, color-mix(in oklch, var(--background) 86%, white) 6%, color-mix(in oklch, var(--background) 95%, var(--foreground)) 38%, color-mix(in oklch, var(--background) 86%, var(--foreground)) 100%)",
  height: "300vmax",
  left: "100%",
  top: "100%",
  transform: `${restAnchor} rotate(${restFold.angle}rad) scaleX(${restFold.depth / flapShadeSpan}) translateY(-50%)`,
  transformOrigin: "0 0",
  width: flapShadeSpan,
};

const undersideShadeStyle: CSSProperties = {
  backgroundImage: "linear-gradient(to right, rgb(0 0 0 / 0.32), transparent)",
  height: "300vmax",
  left: "100%",
  top: "100%",
  transform: `${restAnchor} rotate(${restFold.angle + Math.PI}rad) scaleX(${Math.min(1, restFold.depth / undersideShadeSpan)}) translateY(-50%)`,
  transformOrigin: "0 0",
  width: undersideShadeSpan,
};

const foldHandleStyle: CSSProperties = {
  clipPath: `polygon(0 0, ${foldLeg} 0, 0 ${foldLeg})`,
};

const handleClassNames: Record<PeelHandle, string> = {
  corner: "right-0 bottom-0 size-12",
  fold: "top-0 left-0 size-20",
};

const pointerOf = (event: ReactPointerEvent) => ({
  clientX: event.clientX,
  clientY: event.clientY,
  timeStamp: event.timeStamp,
});

const setDragCursor = (isDragging: boolean) => {
  const root = document.documentElement.style;
  root.cursor = isDragging ? "grabbing" : "";
  root.userSelect = isDragging ? "none" : "";
};

export const usePagePeel = () => {
  const context = use(PagePeelContext);
  if (!context) {
    throw new Error("usePagePeel must be used inside PagePeel");
  }
  return context;
};

const useScrollLock = (isLocked: boolean) => {
  useEffect(() => {
    if (!isLocked) {
      return;
    }
    const root = document.documentElement;
    const previous = root.style.overflow;
    root.style.overflow = "hidden";
    return () => {
      root.style.overflow = previous;
    };
  }, [isLocked]);
};

const useOpenFocus = (
  isOpen: boolean,
  undersideRef: RefObject<HTMLElement | null>,
  returnFocusRef: RefObject<HTMLElement | null>,
  controllerRef: RefObject<PeelController | null>
) => {
  useEffect(() => {
    if (!isOpen) {
      const target = returnFocusRef.current;
      returnFocusRef.current = null;
      if (target?.isConnected) {
        target.focus({ preventScroll: true });
      }
      return;
    }
    undersideRef.current?.focus({ preventScroll: true });
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        controllerRef.current?.close();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, undersideRef, returnFocusRef, controllerRef]);
};

const PeelHandleArea = ({
  controllerRef,
  handle,
  isHidden,
  position,
  undersideRef,
}: {
  controllerRef: RefObject<PeelController | null>;
  handle: PeelHandle;
  isHidden: boolean;
  position: string;
  undersideRef: RefObject<HTMLElement | null>;
}) => {
  const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) {
      return;
    }
    const box = undersideRef.current?.getBoundingClientRect();
    const origin = { x: box?.left ?? 0, y: box?.top ?? 0 };
    if (controllerRef.current?.pointerDown(handle, pointerOf(event), origin)) {
      event.preventDefault();
      event.currentTarget.setPointerCapture(event.pointerId);
      setDragCursor(true);
    }
  };
  const handlePointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
    setDragCursor(false);
    controllerRef.current?.pointerUp(pointerOf(event));
  };
  const handlePointerCancel = () => {
    setDragCursor(false);
    controllerRef.current?.pointerCancel();
  };
  const handleHover =
    (isOver: boolean) => (event: ReactPointerEvent<HTMLDivElement>) => {
      if (event.pointerType !== "touch") {
        controllerRef.current?.hover(handle, isOver);
      }
    };
  return (
    <div
      aria-hidden
      className={cn(
        position,
        handleClassNames[handle],
        "z-50 cursor-grab touch-none select-none active:cursor-grabbing",
        isHidden && "hidden"
      )}
      data-page-peel-handle={handle}
      onPointerCancel={handlePointerCancel}
      onPointerDown={handlePointerDown}
      onPointerEnter={handleHover(true)}
      onPointerLeave={handleHover(false)}
      onPointerMove={(event) =>
        controllerRef.current?.pointerMove(pointerOf(event))
      }
      onPointerUp={handlePointerUp}
      style={handle === "fold" ? foldHandleStyle : undefined}
    />
  );
};

export interface PagePeelProps {
  children: ReactNode;
  className?: string;
  openAt?: number;
  scope?: PeelScope;
  underside: ReactNode;
  undersideClassName?: string;
  undersideLabel?: string;
}

export const PagePeel = ({
  children,
  className,
  openAt = 0.25,
  scope = "viewport",
  underside,
  undersideClassName,
  undersideLabel = "Underside",
}: PagePeelProps) => {
  const undersideId = useId();
  const isReduced = usePrefersReducedMotion();
  const [isOpen, setIsOpen] = useState(false);
  const undersideRef = useRef<HTMLElement>(null);
  const undersideShadeRef = useRef<HTMLDivElement>(null);
  const flapRef = useRef<HTMLDivElement>(null);
  const flapShadeRef = useRef<HTMLDivElement>(null);
  const returnFocusRef = useRef<HTMLElement>(null);
  const controllerRef = useRef<PeelController>(null);
  const isReducedRef = useRef(isReduced);
  const openAtRef = useRef(openAt);

  useEffect(() => {
    isReducedRef.current = isReduced;
    openAtRef.current = openAt;
  }, [isReduced, openAt]);

  useEffect(() => {
    const undersideLayer = undersideRef.current;
    const undersideShade = undersideShadeRef.current;
    const flap = flapRef.current;
    const flapShade = flapShadeRef.current;
    if (!undersideLayer || !undersideShade || !flap || !flapShade) {
      return;
    }
    const controller = createPeelController(
      { flap, flapShade, underside: undersideLayer, undersideShade },
      {
        isReduced: () => isReducedRef.current,
        onOpenChange: setIsOpen,
        openAt: () => openAtRef.current,
      }
    );
    controllerRef.current = controller;
    controller.measure();
    const observer = new ResizeObserver(controller.measure);
    observer.observe(undersideLayer);
    return () => {
      observer.disconnect();
      controller.dispose();
      controllerRef.current = null;
    };
  }, []);

  useScrollLock(isOpen && scope === "viewport");
  useOpenFocus(isOpen, undersideRef, returnFocusRef, controllerRef);

  const toggle = useCallback(() => {
    if (document.activeElement instanceof HTMLElement) {
      returnFocusRef.current = document.activeElement;
    }
    controllerRef.current?.toggle();
  }, []);

  const contextValue = useMemo(
    () => ({ isOpen, toggle, undersideId }),
    [isOpen, toggle, undersideId]
  );

  const position = positionClassNames[scope];

  const layers = (
    <>
      <section
        aria-hidden={!isOpen}
        aria-label={undersideLabel}
        className={cn(
          position,
          "inset-0 z-45 overflow-hidden outline-none",
          isOpen ? "pointer-events-auto" : "pointer-events-none",
          undersideClassName
        )}
        id={undersideId}
        inert={!isOpen}
        ref={undersideRef}
        style={undersideStyle}
        tabIndex={-1}
      >
        <div className="absolute inset-0 overflow-y-auto overscroll-contain">
          {underside}
        </div>
        <div
          aria-hidden
          className="pointer-events-none absolute"
          ref={undersideShadeRef}
          style={undersideShadeStyle}
        />
      </section>
      <div
        aria-hidden
        className={cn(position, "pointer-events-none inset-0 z-50")}
        ref={flapRef}
        style={flapStyle}
      >
        <div className="absolute" ref={flapShadeRef} style={flapShadeStyle} />
      </div>
      <PeelHandleArea
        controllerRef={controllerRef}
        handle="corner"
        isHidden={isOpen}
        position={position}
        undersideRef={undersideRef}
      />
      <PeelHandleArea
        controllerRef={controllerRef}
        handle="fold"
        isHidden={!isOpen}
        position={position}
        undersideRef={undersideRef}
      />
    </>
  );

  if (scope === "container") {
    return (
      <PagePeelContext value={contextValue}>
        <div className={cn("relative isolate overflow-hidden", className)}>
          <div className="h-full" inert={isOpen}>
            {children}
          </div>
          {layers}
        </div>
      </PagePeelContext>
    );
  }

  return (
    <PagePeelContext value={contextValue}>
      <div className={className} inert={isOpen}>
        {children}
      </div>
      {layers}
    </PagePeelContext>
  );
};

export const PagePeelTrigger = ({
  children = "View the underside",
  className,
  ...props
}: Omit<ComponentProps<"button">, "onClick" | "type">) => {
  const { isOpen, toggle, undersideId } = usePagePeel();
  return (
    <button
      aria-controls={undersideId}
      aria-expanded={isOpen}
      className={className}
      onClick={toggle}
      type="button"
      {...props}
    >
      {children}
    </button>
  );
};

import {
  clampToStage,
  easeOutQuart,
  foldCorner,
  openTip,
  peeledShare,
  restingTip,
  settleAxis,
  toClipPath,
} from "@/registry/ivan/lib/page-fold";
import type { Point, Stage } from "@/registry/ivan/lib/page-fold";

export type PeelPhase = "rest" | "dragging" | "opening" | "open" | "closing";

export type PeelHandle = "corner" | "fold";

export interface PeelElements {
  flap: HTMLElement;
  flapShade: HTMLElement;
  underside: HTMLElement;
  undersideShade: HTMLElement;
}

export interface PeelOptions {
  isReduced: () => boolean;
  onOpenChange: (isOpen: boolean) => void;
  openAt: () => number;
}

export interface PeelPointer {
  clientX: number;
  clientY: number;
  timeStamp: number;
}

interface PointerSample {
  time: number;
  x: number;
  y: number;
}

interface DragTrack {
  handle: PeelHandle;
  offset: Point;
  origin: Point;
  samples: PointerSample[];
  start: PointerSample;
  wasOpen: boolean;
}

export const peelLegs = {
  corner: { hover: 48, rest: 28 },
  fold: { hover: 80, rest: 64 },
} as const;

export const flapShadeSpan = 100;
export const undersideShadeSpan = 96;

const tapSlop = 6;
const tapWindow = 450;
const flickSpeed = 0.5;
const settleDuration = 560;
const hoverDuration = 220;
const crossfadeDuration = 200;
const sampleWindow = 90;

const sampleOf = (pointer: PeelPointer, origin: Point): PointerSample => ({
  time: pointer.timeStamp,
  x: pointer.clientX - origin.x,
  y: pointer.clientY - origin.y,
});

const pointerVelocity = (samples: PointerSample[]): Point => {
  const last = samples.at(-1);
  const first =
    samples.find((sample) => last && last.time - sample.time <= sampleWindow) ??
    last;
  if (!first || !last || last.time - first.time < 1) {
    return { x: 0, y: 0 };
  }
  const elapsed = last.time - first.time;
  return { x: (last.x - first.x) / elapsed, y: (last.y - first.y) / elapsed };
};

const tipFromPointer = (
  stage: Stage,
  handle: PeelHandle,
  anchor: Point
): Point =>
  handle === "corner"
    ? anchor
    : { x: 2 * anchor.x - stage.width, y: 2 * anchor.y - stage.height };

const cornerAnchor = (stage: Stage, handle: PeelHandle, tip: Point): Point =>
  handle === "corner"
    ? tip
    : { x: (tip.x + stage.width) / 2, y: (tip.y + stage.height) / 2 };

export const createPeelController = (
  elements: PeelElements,
  options: PeelOptions
) => {
  let phase: PeelPhase = "rest";
  let stage: Stage = { height: 0, width: 0 };
  let tip: Point = { x: 0, y: 0 };
  let leg: number = peelLegs.corner.rest;
  let foldLeg: number = peelLegs.fold.rest;
  let frame = 0;
  let timer = 0;
  let drag: DragTrack | null = null;

  const paint = (next: Point) => {
    tip = next;
    if (stage.width === 0) {
      return;
    }
    const fold = foldCorner(stage, next);
    const anchor = `translate(${fold.midpoint.x - stage.width}px, ${fold.midpoint.y - stage.height}px)`;
    elements.underside.style.clipPath = toClipPath(fold.peeled);
    elements.flap.style.clipPath = toClipPath(fold.flap);
    elements.flapShade.style.transform = `${anchor} rotate(${fold.angle}rad) scaleX(${fold.depth / flapShadeSpan}) translateY(-50%)`;
    elements.undersideShade.style.transform = `${anchor} rotate(${fold.angle + Math.PI}rad) scaleX(${Math.min(1, fold.depth / undersideShadeSpan)}) translateY(-50%)`;
  };

  const stop = () => {
    cancelAnimationFrame(frame);
    window.clearTimeout(timer);
  };

  const restTarget = () => restingTip(stage, leg);
  const openTarget = () => openTip(stage, foldLeg);

  const tweenTo = (target: Point, duration: number) => {
    stop();
    const from = tip;
    const startedAt = performance.now();
    const step = (now: number) => {
      const progress = Math.min(1, (now - startedAt) / duration);
      const eased = easeOutQuart(progress);
      paint({
        x: from.x + (target.x - from.x) * eased,
        y: from.y + (target.y - from.y) * eased,
      });
      if (progress < 1) {
        frame = requestAnimationFrame(step);
      }
    };
    frame = requestAnimationFrame(step);
  };

  const settleTo = (
    target: Point,
    velocity: Point | null,
    onSettled: () => void
  ) => {
    stop();
    const seconds = settleDuration / 1000;
    const curveX = settleAxis(tip.x, target.x, velocity?.x ?? null, seconds);
    const curveY = settleAxis(tip.y, target.y, velocity?.y ?? null, seconds);
    const startedAt = performance.now();
    const step = (now: number) => {
      const progress = (now - startedAt) / settleDuration;
      if (progress >= 1) {
        paint(target);
        onSettled();
        return;
      }
      paint({ x: curveX(progress), y: curveY(progress) });
      frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
  };

  const crossfade = (target: Point, onDone: () => void) => {
    stop();
    elements.underside.style.transition = `opacity ${crossfadeDuration}ms ease`;
    elements.underside.style.opacity = "0";
    timer = window.setTimeout(() => {
      elements.underside.style.transition = "none";
      paint(target);
      elements.underside.getBoundingClientRect();
      elements.underside.style.transition = `opacity ${crossfadeDuration}ms ease`;
      elements.underside.style.opacity = "1";
      onDone();
    }, crossfadeDuration);
  };

  const settleOpen = () => {
    phase = "open";
  };

  const settleRest = () => {
    phase = "rest";
  };

  const isOpenish = () => phase === "open" || phase === "opening";

  const open = (velocity: Point | null = null) => {
    phase = "opening";
    foldLeg = peelLegs.fold.rest;
    options.onOpenChange(true);
    if (options.isReduced()) {
      crossfade(openTarget(), settleOpen);
      return;
    }
    settleTo(openTarget(), velocity, settleOpen);
  };

  const close = (velocity: Point | null = null) => {
    phase = "closing";
    leg = peelLegs.corner.rest;
    options.onOpenChange(false);
    if (options.isReduced()) {
      crossfade(restTarget(), settleRest);
      return;
    }
    settleTo(restTarget(), velocity, settleRest);
  };

  const hover = (handle: PeelHandle, isOver: boolean) => {
    if (options.isReduced()) {
      return;
    }
    const legs = peelLegs[handle];
    const nextLeg = isOver ? legs.hover : legs.rest;
    if (handle === "corner" && phase === "rest") {
      leg = nextLeg;
      tweenTo(restTarget(), hoverDuration);
    } else if (handle === "fold" && phase === "open") {
      foldLeg = nextLeg;
      tweenTo(openTarget(), hoverDuration);
    }
  };

  const pointerDown = (
    handle: PeelHandle,
    pointer: PeelPointer,
    origin: Point
  ) => {
    if (phase === "dragging") {
      return false;
    }
    stop();
    const start = sampleOf(pointer, origin);
    const anchor = cornerAnchor(stage, handle, tip);
    drag = {
      handle,
      offset: { x: anchor.x - start.x, y: anchor.y - start.y },
      origin,
      samples: [start],
      start,
      wasOpen: isOpenish(),
    };
    phase = "dragging";
    return true;
  };

  const pointerMove = (pointer: PeelPointer) => {
    if (phase !== "dragging" || !drag) {
      return;
    }
    const sample = sampleOf(pointer, drag.origin);
    drag.samples = [...drag.samples.slice(-7), sample];
    if (options.isReduced()) {
      return;
    }
    paint(
      clampToStage(
        stage,
        tipFromPointer(stage, drag.handle, {
          x: sample.x + drag.offset.x,
          y: sample.y + drag.offset.y,
        })
      )
    );
  };

  const pointerUp = (pointer: PeelPointer) => {
    const track = drag;
    drag = null;
    if (phase !== "dragging" || !track) {
      return;
    }
    const sample = sampleOf(pointer, track.origin);
    const samples = [...track.samples, sample];
    const isTap =
      Math.hypot(sample.x - track.start.x, sample.y - track.start.y) <
        tapSlop && sample.time - track.start.time < tapWindow;
    if (isTap || options.isReduced()) {
      if (track.wasOpen) {
        close();
      } else if (isTap) {
        open();
      } else {
        phase = "rest";
      }
      return;
    }
    const scale = track.handle === "corner" ? 1000 : 2000;
    const pointerSpeed = pointerVelocity(samples);
    const velocity = { x: pointerSpeed.x * scale, y: pointerSpeed.y * scale };
    const diagonal = Math.hypot(stage.width, stage.height);
    const towardOpen =
      -(pointerSpeed.x * stage.width + pointerSpeed.y * stage.height) /
      diagonal;
    const shouldOpen =
      Math.abs(towardOpen) > flickSpeed
        ? towardOpen > 0
        : peeledShare(stage, tip) > options.openAt();
    if (shouldOpen) {
      open(velocity);
    } else {
      close(velocity);
    }
  };

  const pointerCancel = () => {
    const track = drag;
    drag = null;
    if (phase !== "dragging" || !track) {
      return;
    }
    if (track.wasOpen) {
      open();
    } else {
      close();
    }
  };

  const measure = () => {
    stage = {
      height: elements.underside.clientHeight,
      width: elements.underside.clientWidth,
    };
    if (phase === "open") {
      paint(openTarget());
    } else if (phase === "rest") {
      paint(restTarget());
    }
  };

  return {
    close: () => {
      if (isOpenish()) {
        close();
      }
    },
    dispose: stop,
    hover,
    measure,
    pointerCancel,
    pointerDown,
    pointerMove,
    pointerUp,
    toggle: () => (isOpenish() ? close() : open()),
  };
};

export type PeelController = ReturnType<typeof createPeelController>;

export interface Point {
  x: number;
  y: number;
}

export interface Stage {
  height: number;
  width: number;
}

export interface Fold {
  angle: number;
  depth: number;
  flap: Point[];
  midpoint: Point;
  peeled: Point[];
}

const minimumReach = 0.5;

const dot = (a: Point, b: Point) => a.x * b.x + a.y * b.y;

const stageCorners = ({ width, height }: Stage): Point[] => [
  { x: 0, y: 0 },
  { x: width, y: 0 },
  { x: width, y: height },
  { x: 0, y: height },
];

const keepSide = (polygon: Point[], side: (point: Point) => number) => {
  const kept: Point[] = [];
  for (const [index, current] of polygon.entries()) {
    const next = polygon[(index + 1) % polygon.length] ?? current;
    const currentSide = side(current);
    const nextSide = side(next);
    if (currentSide >= 0) {
      kept.push(current);
    }
    if (currentSide >= 0 !== nextSide >= 0) {
      const share = currentSide / (currentSide - nextSide);
      kept.push({
        x: current.x + (next.x - current.x) * share,
        y: current.y + (next.y - current.y) * share,
      });
    }
  }
  return kept;
};

export const clampToStage = (stage: Stage, point: Point): Point => ({
  x: Math.min(point.x, stage.width - minimumReach),
  y: Math.min(point.y, stage.height - minimumReach),
});

export const foldCorner = (stage: Stage, tip: Point): Fold => {
  const corner = { x: stage.width, y: stage.height };
  const reach = { x: corner.x - tip.x, y: corner.y - tip.y };
  const length = Math.max(Math.hypot(reach.x, reach.y), minimumReach);
  const normal = { x: reach.x / length, y: reach.y / length };
  const midpoint = { x: (corner.x + tip.x) / 2, y: (corner.y + tip.y) / 2 };
  const offset = (point: Point) =>
    dot({ x: point.x - midpoint.x, y: point.y - midpoint.y }, normal);
  const peeled = keepSide(stageCorners(stage), offset);
  const flap = peeled.map((point) => {
    const distance = 2 * offset(point);
    return {
      x: point.x - distance * normal.x,
      y: point.y - distance * normal.y,
    };
  });
  return {
    angle: Math.atan2(-normal.y, -normal.x),
    depth: length / 2,
    flap,
    midpoint,
    peeled,
  };
};

export const restingTip = (stage: Stage, leg: number): Point => ({
  x: stage.width - leg,
  y: stage.height - leg,
});

export const openTip = (stage: Stage, leg: number): Point => ({
  x: leg - stage.height,
  y: leg - stage.width,
});

export const polygonArea = (polygon: Point[]) => {
  let twiceArea = 0;
  for (const [index, point] of polygon.entries()) {
    const next = polygon[(index + 1) % polygon.length] ?? point;
    twiceArea += point.x * next.y - next.x * point.y;
  }
  return Math.abs(twiceArea / 2);
};

export const peeledShare = (stage: Stage, tip: Point) =>
  polygonArea(foldCorner(stage, tip).peeled) / (stage.width * stage.height);

export const settleAxis = (
  from: number,
  to: number,
  velocity: number | null,
  seconds: number
) => {
  const distance = to - from;
  const limit = (3 * Math.abs(distance)) / seconds;
  const launch =
    velocity === null
      ? 3 * (distance / seconds)
      : Math.max(-limit, Math.min(limit, velocity * Math.sign(distance))) *
        Math.sign(distance);
  return (progress: number) => {
    const t = Math.min(1, Math.max(0, progress));
    const t2 = t * t;
    const t3 = t2 * t;
    return (
      from + distance * (3 * t2 - 2 * t3) + launch * seconds * (t3 - 2 * t2 + t)
    );
  };
};

export const toClipPath = (polygon: Point[]) =>
  polygon.length < 3
    ? "polygon(0 0, 0 0, 0 0)"
    : `polygon(${polygon
        .map(({ x, y }) => `${x.toFixed(2)}px ${y.toFixed(2)}px`)
        .join(", ")})`;

export const easeOutQuart = (progress: number) => 1 - (1 - progress) ** 4;

"use client";

import { useSyncExternalStore } from "react";

const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  const mediaQuery = window.matchMedia(reducedMotionQuery);
  mediaQuery.addEventListener("change", onChange);
  return () => mediaQuery.removeEventListener("change", onChange);
};

const getSnapshot = () => window.matchMedia(reducedMotionQuery).matches;

const getServerSnapshot = () => false;

export const usePrefersReducedMotion = () =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
